import { agent, s, workflow } from "rig";
import { readFileSync } from "node:fs";

type Pr = { number: number; title: string; body?: string; labels?: unknown[]; url: string };

// Agent role: partition one chunk of PRs into local groups plus outliers.
const mapChunk = agent({
  name: "mapChunk",
  model: "small",
  input: s.object({ prs: s.string }),
  output: s.object({
    groups: s.array(s.object({ label: s.string, summary: s.string, prs: s.array(s.int) })),
    outliers: s.array(s.object({ pr: s.int, reason: s.string })),
  }),
  instructions:
    "Each line is a merged PR: number | labels | title | body excerpt. Partition ALL listed PRs into local groups of PRs sharing one specific engineering concern. A group needs 2+ PRs; PRs that fit nowhere go to outliers with a reason. Every listed number must appear exactly once. Use only listed numbers.",
});

// Agent role: reduce local groups from all chunks into global themes.
const reduceGroups = agent({
  name: "reduceGroups",
  model: "small",
  input: s.object({ groups: s.string }),
  output: s.object({
    themes: s.array(s.object({ label: s.string, summary: s.string, groupIds: s.array(s.string) })),
  }),
  instructions:
    "Each line is a local PR group: id | label | summary. Merge groups that describe the same theme across chunks into global themes with a short thematic label and an evidence-grounded one-sentence summary. Every group id must appear in exactly one theme. Use only listed ids.",
});

const clean = (t = "") => t.replace(/https?:\S+/g, "").replace(/\s+/g, " ").trim();

// Workflow role: map-reduce clustering of merged PRs, chunk-local grouping then global theme merge.
export default workflow({
  meta: {
    name: "map-reduce-local-group-merge",
    description: "Chunk-local grouping by model, global theme merge by model, TypeScript validation",
    phases: ["Map", "Reduce"],
  },
  body: async ({ call, phase }) => {
    const corpus = JSON.parse(readFileSync("/tmp/gh-aw/agent/merged-prs.json", "utf8"));
    const prs: Pr[] = corpus.prs;
    const nums = new Set(prs.map((p) => p.number));
    if (prs.length === 0 || nums.size !== prs.length) throw new Error("bad corpus");

    const ordered = [...prs].sort((a, b) => a.number - b.number);
    const size = 8;
    const chunks: Pr[][] = [];
    for (let i = 0; i < ordered.length; i += size) chunks.push(ordered.slice(i, i + size));
    if (chunks.length > 10) throw new Error("too many chunks");

    phase("Map");
    const mapped = await Promise.all(
      chunks.map((c, i) =>
        call(
          mapChunk,
          {
            prs: c
              .map((p) => `${p.number} | ${(p.labels ?? []).map((l) => (typeof l === "string" ? l : JSON.stringify(l))).join(",")} | ${p.title} | ${clean(p.body).slice(0, 300)}`)
              .join("\n"),
          },
          { label: `chunk${i}` },
        ),
      ),
    );

    const local = new Map<string, { label: string; summary: string; prs: number[] }>();
    const outliers = new Map<number, string>();
    mapped.forEach((m, i) => {
      if (!m) throw new Error(`missing map response ${i}`);
      const allowed = new Set(chunks[i].map((p) => p.number));
      const seen = new Set<number>();
      const take = (n: number) => {
        if (!allowed.has(n) || seen.has(n)) throw new Error(`chunk ${i}: invalid or duplicate PR ${n}`);
        seen.add(n);
      };
      m.groups.forEach((g, k) => {
        g.prs.forEach(take);
        if (g.prs.length > 0) local.set(`g${i}_${k}`, { label: g.label, summary: g.summary, prs: g.prs });
      });
      m.outliers.forEach((o) => {
        take(o.pr);
        outliers.set(o.pr, o.reason || "No local peer in its chunk");
      });
      if (seen.size !== allowed.size) throw new Error(`chunk ${i}: incomplete coverage`);
    });

    phase("Reduce");
    const reduced = await call(
      reduceGroups,
      { groups: [...local].map(([id, g]) => `${id} | ${g.label} | ${g.summary}`).join("\n") },
      { label: "reduce" },
    );
    if (!reduced) throw new Error("missing reduce response");
    const used = new Set<string>();
    const clusters = reduced.themes
      .map((t) => {
        const members: number[] = [];
        for (const id of t.groupIds) {
          if (!local.has(id) || used.has(id)) throw new Error(`invalid or duplicate group ${id}`);
          used.add(id);
          members.push(...local.get(id)!.prs);
        }
        members.sort((a, b) => a - b);
        return { id: `t${String(members[0] ?? 0).padStart(5, "0")}`, label: t.label, summary: t.summary, prs: members, size: members.length };
      })
      .filter((c) => c.size > 0)
      .sort((x, y) => y.size - x.size || x.id.localeCompare(y.id));
    if (used.size !== local.size) throw new Error("reduce missed local groups");

    const unclassified = [...outliers].map(([pr, reason]) => ({ pr, reason })).sort((a, b) => a.pr - b.pr);
    const seenAll = new Set<number>();
    for (const n of [...clusters.flatMap((c) => c.prs), ...unclassified.map((u) => u.pr)]) {
      if (!nums.has(n) || seenAll.has(n)) throw new Error(`invalid or duplicate PR ${n}`);
      seenAll.add(n);
    }
    if (seenAll.size !== prs.length) throw new Error("incomplete coverage");
    if (new Set(clusters.map((c) => c.id)).size !== clusters.length) throw new Error("duplicate cluster id");

    return {
      repository: corpus.repository,
      window: corpus.window,
      strategy: "Map-reduce: chunk-local model grouping, then model merge of local group descriptors into global themes",
      totalPrs: prs.length,
      modelCalls: chunks.length + 1,
      clusters,
      topThree: clusters.slice(0, 3).map((c) => c.id),
      unclassified,
    };
  },
});
